body.script:
(function () {
    var form = document.getElementById("oo_apply_form");
    if (!form) { return; }
    var steps = Array.prototype.slice.call(
        form.querySelectorAll(".o_oo_step"));
    var progress = Array.prototype.slice.call(
        document.querySelectorAll("#oo_progress li"));
    var back = document.getElementById("oo_back");
    var next = document.getElementById("oo_next");
    var submit = document.getElementById("oo_submit");
    var current = 1;

    function show(step) {
        current = Math.min(Math.max(step, 1), steps.length);
        steps.forEach(function (el) {
            el.classList.toggle(
                "active",
                parseInt(el.dataset.step, 10) === current);
        });
        progress.forEach(function (el) {
            var n = parseInt(el.dataset.step, 10);
            el.classList.toggle("active", n === current);
            el.classList.toggle("done", n < current);
        });
        back.hidden = current === 1;
        next.hidden = current === steps.length;
        submit.hidden = current !== steps.length;
        // The Submit button replaces Continue in the
        // same position. Hold it briefly so a rapid
        // double click cannot submit step 7 before the
        // declaration checkbox is revealed to the user.
        submit.disabled = current === steps.length;
        if (current === steps.length) {
            setTimeout(function () {
                submit.disabled = false;
            }, 500);
        }
        window.scrollTo({top: 0, behavior: "smooth"});
    }

    function stepValid() {
        var section = steps[current - 1];
        var fields = section.querySelectorAll(
            "input, select, textarea");
        for (var i = 0; i < fields.length; i++) {
            var el = fields[i];
            if (el.disabled || el.type === "hidden") { continue; }
            if (!el.checkValidity()) {
                el.reportValidity();
                return false;
            }
        }
        return true;
    }

    next.addEventListener("click", function () {
        if (next.disabled) { return; }
        if (stepValid()) {
            next.disabled = true;
            show(current + 1);
            setTimeout(function () {
                next.disabled = false;
            }, 350);
        }
    });
    back.addEventListener("click", function () {
        show(current - 1);
    });
    form.addEventListener("submit", function (ev) {
        var declaration = document.getElementById(
            "oo_ApplicationDeclaration");
        if (declaration && !declaration.checked) {
            ev.preventDefault();
            declaration.reportValidity();
            return;
        }
        if (!form.checkValidity()) {
            ev.preventDefault();
            var bad = form.querySelector(":invalid");
            if (bad) { bad.reportValidity(); }
            return;
        }
        // One submission only; the server also requires
        // the declaration, so a missing consent value can
        // never create an application.
        submit.disabled = true;
    });

    // ── formatting helpers ──────────────────────
    window.ooFormatCvor = function (input) {
        var digits = input.value.replace(/[^0-9]/g, "").slice(0, 9);
        input.value = (digits.match(/.{1,3}/g) || []).join("-");
    };
    window.ooFormatPhone = function (input) {
        var d = input.value.replace(/\D/g, "");
        if (d.length === 11 && d.charAt(0) === "1") {
            d = d.slice(1);
        }
        if (d.length === 10) {
            input.value = "+1-" + d.slice(0, 3) + "-" +
                d.slice(3, 6) + "-" + d.slice(6);
        }
    };
    window.ooGroup = function (input, max) {
        var digits = input.value.replace(/[^0-9]/g, "");
        if (max && digits && parseInt(digits, 10) > max) {
            digits = String(max);
        }
        input.value = digits.replace(
            /\B(?=(\d{3})+(?!\d))/g, ",");
    };

    // ── WhatsApp ────────────────────────────────
    var usePhone = document.getElementById("oo_use_contact_phone");
    var customWa = document.getElementById("oo_custom_whatsapp_wrap");
    var waInput = document.getElementById("oo_WhatsAppNumber");
    var phoneInput = document.getElementById("oo_partner_phone");
    var waStatus = document.getElementById("oo_whatsapp_status");
    window.ooSyncWhatsApp = function () {
        var same = usePhone && usePhone.checked;
        if (customWa) { customWa.hidden = same; }
        if (waInput) {
            waInput.disabled = same;
            waInput.required = !same &&
                (document.getElementById(
                    "oo_LoadNotificationChannel").value === "whatsapp" ||
                 document.getElementById(
                    "oo_LoadNotificationChannel").value === "both");
        }
        if (waStatus) { waStatus.hidden = !same; }
    };
    if (phoneInput) {
        phoneInput.addEventListener("input", function () {
            if (usePhone && usePhone.checked) {
                waInput.value = phoneInput.value;
            }
        });
    }

    // ── vehicle conditionals ────────────────────
    var vehicle = document.getElementById("oo_VehicleType");
    var cargoBlock = document.getElementById("oo_cargo_block");
    var trailerBlock = document.getElementById("oo_semi_trailer");
    var tractorNote = document.getElementById("oo_tractor_note");
    var trailerType = document.getElementById("oo_TrailerType");
    var cab = document.getElementById("oo_CabType");
    var cabReq = document.getElementById("oo_cab_req");
    var cabNA = cab ? cab.querySelector(
        'option[value="not_applicable"]') : null;

    function setVisible(el, visible) {
        if (!el) { return; }
        el.hidden = !visible;
        el.querySelectorAll("input, select, textarea")
            .forEach(function (field) {
                field.disabled = !visible;
                if (!visible) {
                    if (field.type === "checkbox") {
                        field.checked = false;
                    } else {
                        field.value = "";
                    }
                }
            });
    }
    function setFieldVisible(id, visible) {
        var el = document.getElementById(id);
        if (!el) { return; }
        el.hidden = !visible;
        el.querySelectorAll("input, select, textarea")
            .forEach(function (field) {
                field.disabled = !visible;
            });
    }

    window.ooSyncReefer = function () {
        var v = vehicle.value;
        var body = document.getElementById("oo_CargoBodyType").value;
        var ttype = trailerType.value;
        var reefer = (v === "cargo_van" || v === "straight")
            ? body === "reefer" : (v === "semi" && ttype === "reefer");
        setFieldVisible("oo_reefer_wrap", reefer);
    };
    window.ooSyncLiftgate = function () {
        var lg = document.getElementById("oo_Liftgate");
        setFieldVisible("oo_liftgate_capacity_wrap",
                        lg && lg.value === "yes");
    };
    window.ooSyncTrailer = function () {
        var t = trailerType.value;
        var v = vehicle.value;
        var cargoVisible = v === "semi" &&
            (t === "dry" || t === "reefer" || t === "flatbed");
        setVisible(cargoBlock, cargoVisible ||
                   v === "cargo_van" || v === "straight");
        setFieldVisible("oo_cargo_body_wrap",
                        v === "cargo_van" || v === "straight");
        var full = v === "cargo_van" || v === "straight" ||
            (v === "semi" && (t === "dry" || t === "reefer"));
        var flat = v === "semi" && t === "flatbed";
        setFieldVisible("oo_payload_wrap", full || flat);
        setFieldVisible("oo_pallet_wrap", full);
        setFieldVisible("oo_length_wrap", full || flat);
        setFieldVisible("oo_width_wrap", full || flat);
        setFieldVisible("oo_height_wrap", full);
        setFieldVisible("oo_door_width_wrap", full);
        setFieldVisible("oo_door_height_wrap", full);
        setFieldVisible("oo_liftgate_wrap", full);
        setFieldVisible("oo_liftgate_capacity_wrap",
                        full && document.getElementById(
                            "oo_Liftgate").value === "yes");
        var body = document.getElementById("oo_CargoBodyType");
        if (v === "semi" && (t === "dry" || t === "reefer")) {
            body.value = t === "reefer" ? "reefer" : "dry";
        }
        ooSyncReefer();
    };
    window.ooSyncVehicle = function () {
        var v = vehicle.value;
        var van = v === "cargo_van" || v === "straight";
        var semi = v === "semi";
        var tractor = v === "tractor";
        if (tractorNote) { tractorNote.hidden = !tractor; }
        setVisible(trailerBlock, semi);
        setFieldVisible("oo_cargo_body_wrap", van);
        setVisible(cargoBlock, van || semi);
        if (semi) {
            ["oo_TrailerType", "oo_TrailerYear",
             "oo_TrailerUnit", "oo_TrailerLengthFt"]
                .forEach(function (id) {
                    var el = document.getElementById(id);
                    if (el) { el.required = true; }
                });
        } else {
            ["oo_TrailerType", "oo_TrailerYear",
             "oo_TrailerUnit", "oo_TrailerLengthFt"]
                .forEach(function (id) {
                    var el = document.getElementById(id);
                    if (el) { el.required = false; }
                });
        }
        ooSyncTrailer();
        ooSyncCab();
    };

    window.ooSyncCab = function () {
        if (!cab) { return; }
        var heavy = vehicle.value === "tractor" ||
            vehicle.value === "semi";
        if (cabNA) { cabNA.disabled = heavy; }
        if (heavy) {
            // "Not Applicable" is not a valid answer for
            // a tractor or semi-truck: force an explicit
            // Day Cab / Night Cab choice.
            if (cab.value === "not_applicable") {
                cab.value = "";
            }
            cab.required = true;
        } else {
            cab.required = false;
            if (!cab.value) {
                cab.value = "not_applicable";
            }
        }
        if (cabReq) { cabReq.hidden = !heavy; }
    };

    // ── operating-area chips ────────────────────
    window.ooSyncServiceChips = function () {
        var box = document.getElementById("oo_service_chips");
        if (!box) { return; }
        box.innerHTML = "";
        form.querySelectorAll(".oo-service-province:checked")
            .forEach(function (cb) {
                var chip = document.createElement("span");
                chip.className = "o_oo_chip";
                chip.textContent = cb.dataset.code;
                var x = document.createElement("button");
                x.type = "button";
                x.setAttribute("aria-label", "Remove " +
                               cb.value);
                x.textContent = "×";
                x.addEventListener("click", function () {
                    cb.checked = false;
                    ooSyncServiceChips();
                });
                chip.appendChild(x);
                box.appendChild(chip);
            });
    };

    // ── notification summary ────────────────────
    window.ooSyncNotification = function () {
        var channel = document.getElementById(
            "oo_LoadNotificationChannel").value;
        var wa = channel === "whatsapp" || channel === "both";
        var em = channel === "email" || channel === "both";
        var consent = document.getElementById(
            "oo_whatsapp_consent_wrap");
        var email = document.getElementById("oo_email_notify_wrap");
        if (consent) { consent.hidden = !wa; }
        if (email) { email.hidden = !em; }
        var consentBox = document.getElementById(
            "oo_WhatsAppConsentGranted");
        if (consentBox) { consentBox.required = wa; }
        var useApp = document.getElementById("oo_use_app_email");
        var emailField = document.getElementById(
            "oo_LoadNotificationEmail");
        if (emailField) {
            emailField.disabled = !em ||
                (useApp && useApp.checked);
            emailField.required = em &&
                !(useApp && useApp.checked);
        }
        ooSyncWhatsApp();
        var summary = document.getElementById("oo_notify_summary");
        if (!summary) { return; }
        var text = "Notifications: ";
        if (channel === "none") {
            text += "no load opportunities will be sent.";
        } else if (channel === "whatsapp") {
            text += "WhatsApp at " + (waInput.value || "the contact phone") + ".";
        } else if (channel === "email") {
            text += "email at " + (useApp && useApp.checked ?
                "the application address" : "the address you enter") + ".";
        } else if (channel === "both") {
            text += "WhatsApp and email.";
        } else {
            text += "not selected.";
        }
        summary.textContent = text;
    };

    // ── Google city autocomplete ────────────────
    var city = document.getElementById("oo_HomeCity");
    var results = document.getElementById("oo_city_results");
    var timer = null;
    function clearSelection() {
        ["oo_HomeCityPlaceId", "oo_HomeCityLat",
         "oo_HomeCityLng", "oo_HomeCityVerified"]
            .forEach(function (id) {
                var el = document.getElementById(id);
                if (el) { el.value = ""; }
            });
        var badge = document.getElementById("oo_city_verified");
        if (badge) { badge.hidden = true; }
    }
    function chooseCity(item) {
        city.value = item.city;
        document.getElementById("oo_HomeProvince").value =
            item.province_code;
        document.getElementById("oo_HomeCityPlaceId").value =
            item.place_id;
        document.getElementById("oo_HomeCityLat").value =
            item.latitude;
        document.getElementById("oo_HomeCityLng").value =
            item.longitude;
        document.getElementById("oo_HomeCityVerified").value = "1";
        var badge = document.getElementById("oo_city_verified");
        if (badge) { badge.hidden = false; }
        results.hidden = true;
        results.innerHTML = "";
    }
    if (city) {
        city.addEventListener("input", function () {
            clearSelection();
            clearTimeout(timer);
            var q = city.value.trim();
            if (q.length < 2) {
                results.hidden = true;
                return;
            }
            timer = setTimeout(function () {
                fetch("/owner-operator/places/cities?q=" +
                      encodeURIComponent(q))
                    .then(function (r) { return r.json(); })
                    .then(function (items) {
                        results.innerHTML = "";
                        (items || []).forEach(function (it) {
                            var b = document.createElement("button");
                            b.type = "button";
                            b.className = "o_oo_city_item";
                            b.textContent = it.label;
                            b.addEventListener("click",
                                function () { chooseCity(it); });
                            results.appendChild(b);
                        });
                        results.hidden =
                            !results.children.length;
                    })
                    .catch(function () {
                        results.hidden = true;
                    });
            }, 250);
        });
    }

    // ── TDG disclosure ─────────────────────────
    window.ooSyncTdg = function () {
        var status = document.getElementById("oo_TDGStatus");
        var box = document.getElementById("oo_tdg_details");
        var current = status && status.value === "current";
        if (box) {
            box.hidden = !current;
            box.querySelectorAll("input, select")
                .forEach(function (el) {
                    el.disabled = !current;
                    if (!current) {
                        if (el.type === "checkbox") {
                            el.checked = false;
                        } else {
                            el.value = "";
                        }
                    }
                });
        }
    };
    window.ooSyncTdgNone = function () {
        var none = document.querySelector(
            "input[name=TDGClassesNone]");
        if (none && none.checked) {
            document.querySelectorAll(
                "input[name^=TDGClass]:not([name=TDGClassesNone])")
                .forEach(function (el) { el.checked = false; });
        }
    };

    // initial state
    show(1);
    ooSyncVehicle();
    ooSyncNotification();
    ooSyncWhatsApp();
    ooSyncLiftgate();
    ooSyncServiceChips();
    ooSyncReefer();
    ooSyncTdg();
})();
